{"code": "export async function main(input: unknown) {
  const { issues } = await sdk.sentry.listIssues({ project: "api" });

  const candidates = issues.filter(i => i.status === "unresolved" && i.count >= 0);

  // unique culprits
  const culprits: string[] = [];
  for (const i of candidates) {
    const c = i.culprit;
    if (c && !culprits.includes(c)) culprits.push(c);
  }

  const report: any[] = [];
  const created: any[] = [];

  for (const culprit of culprits) {
    const { issues: found } = await sdk.linear.searchIssues({ query: culprit });
    const existing = found.filter(l =>
      (l.title ?? "").includes(culprit) || (l.description ?? "").includes(culprit)
    );
    if (existing.length > 0) {
      report.push({ culprit, action: "exists", linear: existing.map(e => e.identifier) });
    } else {
      const ph = await sdk.linear.createIssue({ title: `[Sentry] ${culprit}`, description: culprit });
      created.push(ph);
      report.push({ culprit, action: "create", title: `[Sentry] ${culprit}` });
    }
  }

  return { sentryIssues: candidates.map(i => ({ shortId: i.shortId, culprit: i.culprit, count: i.count })), report, createdCount: created.length };
}"}

